package com.haolin.vontlocal;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;

/** Scene-first launcher; merely opening it never changes a light. */
public final class HomeActivity extends Activity {
    Ui u;TextView status;Button cancel,retry,focusAction;TextView focusTitle,focusDetail;final Handler handler=new Handler(Looper.getMainLooper());boolean resumed;String theme;
    @Override public void onCreate(Bundle saved){Ui.prepare(this);super.onCreate(saved);SceneStore.ensure(this);theme=Ui.appearance(this);}
    void build(){u=new Ui(this);LinearLayout root=u.root(this),body=u.scrollBody(root),top=u.row();top.setPadding(0,u.dp(this,14),0,u.dp(this,16));LinearLayout word=u.column();TextView brand=u.text(word,"栖光",34);brand.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));u.hint(word,"合适的光，陪你过好每一刻");top.addView(word,new LinearLayout.LayoutParams(0,-2,1));u.iconButton(top,"settings","打开栖光设置",()->startActivity(new Intent(this,SettingsActivity.class)));body.addView(top);
        LinearLayout heading=u.row();heading.addView(u.label("你的三个时刻",19,u.text),new LinearLayout.LayoutParams(0,-2,1));Button off=u.button(heading,"全关",()->run("off",false),false);off.setContentDescription("两组灯全关");off.setLayoutParams(new LinearLayout.LayoutParams(u.dp(this,86),u.dp(this,48)));body.addView(heading);u.gap(body,12);for(String id:SceneStore.IDS)sceneCard(body,id);
        LinearLayout result=u.card(body),r=u.row();r.addView(u.label("灯光动态",15,u.muted),new LinearLayout.LayoutParams(0,-2,1));u.iconButton(r,"refresh","刷新两组灯状态",()->run("refresh",false));result.addView(r);status=u.text(result,"",15);status.setTextIsSelectable(true);cancel=u.button(result,"取消延时，保留灯光",()->run("cancel",false),false);retry=u.button(result,"重试未确认操作",()->{JSONObject s=LinkStore.status(this);if(s.length()>0)run(s.optString("action"),true);},false);
        LinearLayout focus=u.card(body),focusLine=u.row();focusTitle=u.label(FocusStore.title(this),19,u.text);focusLine.addView(focusTitle,new LinearLayout.LayoutParams(0,-2,1));focusAction=u.button(focusLine,"开始",()->{if(FocusStore.running())FocusService.end(this,"提醒已结束，保留当前灯光");else FocusConfirmActivity.open(this);render();},true);focusAction.setContentDescription("办公提醒开始或结束");focus.addView(focusLine);focusDetail=u.hint(focus,FocusStore.detail(this));u.button(focus,"提醒参数",()->startActivity(new Intent(this,FocusSettingsActivity.class)),false);
        u.title(body,"我的灯具");deviceCard(body,"vont","Vont 双灯","两路暖光 · 彩色与分段",()->startActivity(new Intent(this,MainActivity.class).putExtra("entryTab","调节")));deviceCard(body,"screenbar","屏幕挂灯 1S","亮度 · 色温 · 专注",()->startActivity(new Intent(this,ScreenbarActivity.class)));u.hint(body,"状态来自最近读取，点击刷新可核对当前灯光。");LinearLayout footer=u.row();u.button(footer,"添加桌面组件",this::pinWidget,false);u.button(footer,"使用帮助",()->startActivity(new Intent(this,SettingsActivity.class)),false);body.addView(footer);u.gap(body,12);render();
    }
    void sceneCard(LinearLayout body,String id){LinearLayout c=u.card(body);c.setBackground(u.touch(u.surface,22));c.setContentDescription("应用"+LinkPolicy.name(id)+"场景");c.setOnClickListener(v->run(id,false));LinearLayout row=u.row();ImageView icon=new ImageView(this);icon.setImageDrawable(new Ui.Mark(id,u.accent));icon.setBackground(u.shape(u.soft,18));icon.setPadding(u.dp(this,12),u.dp(this,12),u.dp(this,12),u.dp(this,12));row.addView(icon,new LinearLayout.LayoutParams(u.dp(this,64),u.dp(this,64)));LinearLayout labels=u.column();LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=u.dp(this,15);row.addView(labels,lp);TextView title=u.text(labels,LinkPolicy.name(id),23);title.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));u.hint(labels,SceneStore.mood(id));u.iconButton(row,"edit","编辑"+LinkPolicy.name(id)+"场景",()->startActivity(new Intent(this,SleepActivity.class).putExtra("sceneId",id)));c.addView(row);u.gap(c,9);u.hint(c,SceneStore.description(this,id)+"   ·   点按启用");}
    void deviceCard(LinearLayout p,String icon,String title,String detail,Runnable open){LinearLayout card=u.card(p),r=u.row();ImageView i=new ImageView(this);i.setImageDrawable(new Ui.Mark(icon,u.accent));r.addView(i,new LinearLayout.LayoutParams(u.dp(this,40),u.dp(this,40)));LinearLayout labels=u.column();LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,-2,1);lp.leftMargin=u.dp(this,14);r.addView(labels,lp);u.text(labels,title,18);u.hint(labels,detail+"  ›");card.addView(r);card.setContentDescription("打开"+title+"控制");card.setBackground(u.touch(u.surface,22));card.setOnClickListener(v->open.run());}
    void run(String action,boolean retry){LinkService.start(this,action,"app",retry);handler.postDelayed(this::render,150);}
    void render(){if(focusTitle!=null){focusTitle.setText(FocusStore.title(this));focusDetail.setText(FocusStore.detail(this));focusAction.setText(FocusStore.running()?"结束":"开始");}JSONObject s=LinkStore.status(this);String value=s.length()==0?"选一个场景，灯光就准备好了。":LinkStore.summary(this);if(!value.contentEquals(status.getText()))status.setText(value);String state=LinkStore.plan(this).optString("state");cancel.setVisibility("armed".equals(state)||"changed".equals(state)||"overdue".equals(state)||"failed".equals(state)?View.VISIBLE:View.GONE);boolean failed=false;for(String k:new String[]{"vont","screenbar"}){JSONObject v=s.optJSONObject(k);failed|=v!=null&&"failed".equals(v.optString("status"));}retry.setVisibility(s.optBoolean("completed")&&failed?View.VISIBLE:View.GONE);}
    void pinWidget(){AppWidgetManager m=AppWidgetManager.getInstance(this);if(m.isRequestPinAppWidgetSupported()&&m.requestPinAppWidget(new ComponentName(this,LinkWidget.class),null,null))Toast.makeText(this,"请在桌面的添加窗口确认",1).show();else new AlertDialog.Builder(this).setTitle("添加栖光组件").setMessage("长按桌面空白处，打开组件列表，找到栖光。vivo 可从原子组件底部的“应用挂件”进入。组件可以拖动边缘调整大小。").setPositiveButton("知道了",null).show();}
    final Runnable ticker=new Runnable(){public void run(){if(resumed){render();handler.postDelayed(this,800);}}};
    @Override public void onResume(){super.onResume();if(theme!=null&&!theme.equals(Ui.appearance(this))){recreate();return;}resumed=true;build();handler.post(ticker);}
    @Override public void onPause(){resumed=false;handler.removeCallbacks(ticker);super.onPause();}
    @Override public void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
}
